import './globals.css';
import type { Metadata } from 'next';
import { Fraunces, Hanken_Grotesk } from 'next/font/google';

const sans = Hanken_Grotesk({
  subsets: ['latin'],
  weight: ['400', '600'],
  variable: '--font-sans',
});

const display = Fraunces({
  subsets: ['latin'],
  weight: ['600'],
  variable: '--font-display',
});

export const metadata: Metadata = {
  metadataBase: new URL('https://kaambol.in'),
  title: 'KaamBol: Bolo, kaam pao.',
  description:
    'Speak your home-service problem in Hindi, Bengali, Tamil or English. KaamBol finds the nearest verified worker, shows them on a map and books in one tap.',
  openGraph: {
    title: 'KaamBol: Bolo, kaam pao.',
    description:
      'Voice-first booking for trusted, verified home-service workers near you.',
    images: [
      {
        url: 'https://bolt.new/static/og_default.png',
      },
    ],
  },
  twitter: {
    card: 'summary_large_image',
    images: [
      {
        url: 'https://bolt.new/static/og_default.png',
      },
    ],
  },
};

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <html lang="en" className={`${sans.variable} ${display.variable}`}>
      <body className="bg-paper font-sans text-ink antialiased">{children}</body>
    </html>
  );
}